using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker(reorderThreshold: 5);

    // ── Constructor ──────────────────────────────────────────────

    [TestMethod]
    public void Constructor_DefaultThreshold_DoesNotThrow()
    {
        var tracker = new InventoryTracker();
        Assert.AreEqual(0, tracker.GetStockLevel("ANY"));
    }

    [TestMethod]
    public void Constructor_NegativeThreshold_Throws()
        => Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => new InventoryTracker(reorderThreshold: -1));

    // ── GetStockLevel ────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
        => Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));

    // ── AddStock ─────────────────────────────────────────────────

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 20);
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddStock_NonPositiveQuantity_Throws(int qty)
        => Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", qty));

    [TestMethod]
    public void AddStock_NullSku_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(null!, 1));

    // ── RemoveStock ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_SufficientStock_DecreasesLevel()
    {
        _tracker.AddStock("SKU-B", 10);
        _tracker.RemoveStock("SKU-B", 3);
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void RemoveStock_ExactStock_LeavesZero()
    {
        _tracker.AddStock("SKU-B", 5);
        _tracker.RemoveStock("SKU-B", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-B", 2);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-B", 10));
    }

    [TestMethod]
    public void RemoveStock_NonPositiveQuantity_Throws()
        => Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-B", 0));

    // ── NeedsReorder ─────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-C", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-C", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-C", 100);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
        => Assert.IsTrue(_tracker.NeedsReorder("MISSING"));

    [TestMethod]
    public void NeedsReorder_NullSku_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.NeedsReorder(null!));

    // ── AssignWarehouse ──────────────────────────────────────────

    [TestMethod]
    public void AssignWarehouse_ValidInputs_DoesNotThrow()
        => _tracker.AssignWarehouse("SKU-D", "WH-1");

    [TestMethod]
    public void AssignWarehouse_NullSku_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.AssignWarehouse(null!, "WH-1"));

    [TestMethod]
    public void AssignWarehouse_NullWarehouse_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.AssignWarehouse("SKU-D", null!));

    // ── TransferStock ────────────────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesStockBetweenTrackers()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-E", 20);

        _tracker.TransferStock("SKU-E", 8, dest);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-E"));
        Assert.AreEqual(8, dest.GetStockLevel("SKU-E"));
    }

    [TestMethod]
    public void TransferStock_InsufficientStock_Throws()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-E", 2);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-E", 10, dest));
    }

    [TestMethod]
    public void TransferStock_NullDestination_Throws()
    {
        _tracker.AddStock("SKU-E", 5);
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-E", 1, null!));
    }

    [TestMethod]
    public void TransferStock_FailedTransfer_DoesNotAlterSource()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-F", 3);

        try { _tracker.TransferStock("SKU-F", 10, dest); } catch { }

        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-F"),
            "Source stock should remain unchanged after failed transfer.");
        Assert.AreEqual(0, dest.GetStockLevel("SKU-F"),
            "Destination should not receive stock after failed transfer.");
    }
}

